SELECT 
FROM tb_reservation_batch b
LEFT JOIN tb_equipment e ON b.equipment_id = e.id
LEFT JOIN tb_laboratory l ON e.laboratory_id = l.id


        AND b.equipment_id = #{q.equipmentId}


        AND e.laboratory_id = #{q.laboratoryId}


        AND b.status = #{q.status}


        AND b.status IN ('PUBLISHED', 'CLOSED')


        AND l.admin_user_id = #{adminUserId}


ORDER BY b.id DESC
